@js:
classList=[];
push=(title,url,type1,type2)=>classList.push({
	title: title,
	url: url,
	style: {
		layout_flexGrow: type1,
		layout_flexBasisPercent: type2
	}
});

typeMap=["1000","1002","1003","5005","1001","1005","5004","5003"];

type=["全部","故事","乱伦","现代","熟女","武侠","侵犯","其它"];
push('✿                  分类                  ✿', null, 1, 1);
type.map((title,index)=>{
	url= `https://xoxiaoshuo.com/arttype/${typeMap[index]}-{{page}}/`;
	index++;
